async function maybeDriveBackup(){if(!cfg().driveAutoBackup||!driveReady()||driveBackupBusy||Date.now()-lastDriveAttempt<300000||Date.now()-Date.parse(cfg().lastDriveBackup||'1970-01-01')<86400000)return;lastDriveAttempt=Date.now();try{await saveDriveBackup(true)}catch(error){status('Synced · Drive backup pending')}}

async function uploadLargeDriveFile(metadata,media){const start=await fetch('https://www.googleapis.com/upload/drive/v3/files?uploadType=resumable&fields=id,name&supportsAllDrives=true',{method:'POST',headers:{Authorization:'Bearer '+driveToken,'Content-Type':'application/json','X-Upload-Content-Type':media.type,'X-Upload-Content-Length':String(media.size)},body:JSON.stringify(metadata)});if(!start.ok)throw Error('Drive could not start the backup upload. Retry after reconnecting.');const session=start.headers.get('Location');if(!session||!session.startsWith('https://www.googleapis.com/upload/drive/'))throw Error('Drive returned an invalid upload session.');const response=await fetch(session,{method:'PUT',headers:{Authorization:'Bearer '+driveToken,'Content-Type':media.type},body:media});if(!response.ok)throw Error('Drive backup upload was interrupted. Retry the backup.');return response.json()}

async function checkGatekeeper(){const output=$('#gatekeeperStatus');output.textContent='Checking the server-side Artlook connection…';try{const response=await fetch('/api/drive/list',{method:'POST',headers:{Authorization:'Bearer '+cryptoKeys.auth,'Content-Type':'application/json'},body:'{}'}),data=await response.json();if(!response.ok)throw Error(data.error||'Gatekeeper check failed');output.textContent='Read-only gatekeeper connected · '+data.files.length+' files returned from the planner folder. Google OAuth is required to upload images and backups.';}catch(error){output.textContent=error.message}}

